from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}
    k = len(alphabet)

    nxt = [[-1] * k]
    bad = [False]

    for word in banned:
        u = 0
        for ch in word:
            c = char_to_idx[ch]
            if nxt[u][c] == -1:
                nxt[u][c] = len(nxt)
                nxt.append([-1] * k)
                bad.append(False)
            u = nxt[u][c]
        bad[u] = True

    fail = [0] * len(nxt)
    q = deque()
    for c in range(k):
        v = nxt[0][c]
        if v != -1:
            fail[v] = 0
            q.append(v)
        else:
            nxt[0][c] = 0

    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for c in range(k):
            v = nxt[u][c]
            if v != -1:
                fail[v] = nxt[fail[u]][c]
                q.append(v)
            else:
                nxt[u][c] = nxt[fail[u]][c]

    good_id = [-1] * len(nxt)
    m = 0
    for u in range(len(nxt)):
        if not bad[u]:
            good_id[u] = m
            m += 1

    mat = [[0] * m for _ in range(m)]
    for u in range(len(nxt)):
        if bad[u]:
            continue
        iu = good_id[u]
        for c in range(k):
            v = nxt[u][c]
            if not bad[v]:
                mat[iu][good_id[v]] += 1

    vec = [0] * m
    vec[good_id[0]] = 1

    exp = n
    while exp > 0:
        if exp & 1:
            new_vec = [0] * m
            for i in range(m):
                vi = vec[i]
                if vi:
                    row = mat[i]
                    for j in range(m):
                        new_vec[j] = (new_vec[j] + vi * row[j]) % MOD
            vec = new_vec
        exp >>= 1
        if exp > 0:
            new_mat = [[0] * m for _ in range(m)]
            for i in range(m):
                row_i = mat[i]
                res_i = new_mat[i]
                for p in range(m):
                    val = row_i[p]
                    if val:
                        row_p = mat[p]
                        for j in range(m):
                            res_i[j] = (res_i[j] + val * row_p[j]) % MOD
            mat = new_mat

    return sum(vec) % MOD
